/**
 * Card encoding: integers 0..51.
 *   rank = card >> 2   (0 = deuce, ..., 8 = ten, 12 = ace)
 *   suit = card & 3    (0 = s, 1 = h, 2 = d, 3 = c)
 */

export const RANK_CHARS = "23456789TJQKA";
export const SUIT_CHARS = "shdc";

export function makeCard(rank: number, suit: number): number {
  return ((rank & 15) << 2) | (suit & 3);
}

export function parseCard(s: string): number {
  const r = RANK_CHARS.indexOf(s[0].toUpperCase());
  const u = SUIT_CHARS.indexOf(s[1].toLowerCase());
  if (r < 0 || u < 0) throw new Error(`bad card: ${s}`);
  return makeCard(r, u);
}

export function parseHand(s: string): number[] {
  return s.trim().split(/\s+/).map(parseCard);
}

export function cardToString(c: number): string {
  return RANK_CHARS[c >> 2] + SUIT_CHARS[c & 3];
}

// Hand categories (higher wins).
const HIGH_CARD = 0;
const PAIR = 1;
const TWO_PAIR = 2;
const TRIPS = 3;
const STRAIGHT = 4;
const FLUSH = 5;
const FULL_HOUSE = 6;
const QUADS = 7;
const STRAIGHT_FLUSH = 8;

/** Straight high card from a sorted-descending list of distinct ranks, or -1. */
function straightHigh(distinctDesc: number[]): number {
  // Wheel check first (ace plays low): A,5,4,3,2 -> high card 5 (rank value 3).
  if (
    distinctDesc.length >= 5 &&
    distinctDesc[0] === 12 &&
    distinctDesc.includes(3) &&
    distinctDesc.includes(2) &&
    distinctDesc.includes(1) &&
    distinctDesc.includes(0)
  ) {
    return 3;
  }
  for (let i = 0; i + 4 < distinctDesc.length; i++) {
    let ok = true;
    for (let j = 1; j < 5; j++) {
      if (distinctDesc[i] - distinctDesc[i + j] !== j) {
        ok = false;
        break;
      }
    }
    if (ok) return distinctDesc[i];
  }
  return -1;
}

/**
 * Evaluate exactly 5 cards, returning a totally ordered integer score:
 * category << 20 | kickers packed as 5 nibbles (base 16).
 */
export function eval5(cards: number[]): number {
  if (cards.length !== 5) throw new Error("eval5 requires exactly 5 cards");

  const counts = new Array(13).fill(0);
  const suitMask = new Array(4).fill(0);
  let suitAll = -1;
  let flush = true;
  for (const c of cards) {
    const r = c >> 2;
    const s = c & 3;
    counts[r]++;
    if (suitAll === -1) suitAll = s;
    else if (suitAll !== s) flush = false;
    void suitMask;
  }

  // Distinct ranks descending, grouped by multiplicity.
  const quadsR: number[] = [];
  const tripsR: number[] = [];
  const pairsR: number[] = [];
  const singlesR: number[] = [];
  for (let r = 12; r >= 0; r--) {
    switch (counts[r]) {
      case 4: quadsR.push(r); break;
      case 3: tripsR.push(r); break;
      case 2: pairsR.push(r); break;
      case 1: singlesR.push(r); break;
    }
  }

  const pack = (vals: number[]): number => {
    let v = 0;
    for (let i = 0; i < 5; i++) v = (v << 4) | (vals[i] ?? 0);
    return v;
  };

  const distinct = [...quadsR, ...tripsR, ...pairsR, ...singlesR];

  if (flush) {
    const sh = straightHigh(singlesR.concat(...pairsR, ...tripsR, ...quadsR).sort((a, b) => b - a));
    if (sh >= 0) return (STRAIGHT_FLUSH << 20) | pack([sh]);
  }
  if (quadsR.length === 1) {
    return (QUADS << 20) | pack([quadsR[0], singlesR[0] ?? pairsR[0]]);
  }
  if (tripsR.length >= 1 && (pairsR.length >= 1 || tripsR.length >= 2)) {
    const trips = tripsR[0];
    const pair = pairsR[0] ?? tripsR[1];
    return (FULL_HOUSE << 20) | pack([trips, pair]);
  }
  if (flush) {
    return (FLUSH << 20) | pack(singlesR);
  }
  const sh = straightHigh(distinct);
  if (sh >= 0) {
    return (STRAIGHT << 20) | pack([sh]);
  }
  if (tripsR.length === 1) {
    return (TRIPS << 20) | pack([tripsR[0], ...singlesR]);
  }
  if (pairsR.length >= 2) {
    return (TWO_PAIR << 20) | pack([pairsR[0], pairsR[1], singlesR[0] ?? 0]);
  }
  if (pairsR.length === 1) {
    return (PAIR << 20) | pack([pairsR[0], ...singlesR]);
  }
  return (HIGH_CARD << 20) | pack(singlesR);
}

const COMBOS_7_CHOOSE_5: number[][] = (() => {
  const out: number[][] = [];
  for (let a = 0; a < 3; a++)
    for (let b = a + 1; b < 4; b++)
      for (let c = b + 1; c < 5; c++)
        for (let d = c + 1; d < 6; d++)
          for (let e = d + 1; e < 7; e++) out.push([a, b, c, d, e]);
  return out; // 21 combinations
})();

/**
 * Best 5-of-7 evaluation: reuses eval5 over all C(7,5) subsets
 * and returns the maximum score.
 */
export function eval7(cards: number[]): number {
  if (cards.length !== 7) throw new Error("eval7 requires exactly 7 cards");
  let best = 0;
  for (let i = 0; i < COMBOS_7_CHOOSE_5.length; i++) {
    const idx = COMBOS_7_CHOOSE_5[i];
    const score = eval5([cards[idx[0]], cards[idx[1]], cards[idx[2]], cards[idx[3]], cards[idx[4]]]);
    if (score > best) best = score;
  }
  return best;
}

