import { eval7, makeCard } from "./eval7";

export type EquityResult = {
  /** Number of deals where AA wins outright. */
  wins: number;
  /** Number of deals where the pot is split. */
  splits: number;
  /** Number of deals where 22 wins outright. */
  losses: number;
  /** (wins + splits/2) / deals */
  equity: number;
};

/** Deterministic PRNG: mulberry32. Returns floats in [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function (): number {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function fullDeck(): number[] {
  const deck: number[] = [];
  for (let r = 0; r < 13; r++) for (let s = 0; s < 4; s++) deck.push(makeCard(r, s));
  return deck;
}

/**
 * Monte Carlo all-in preflop equity of AA vs 22 over `deals` random boards,
 * using a seeded mulberry32 RNG (fully deterministic per seed).
 */
export function simulateAAvs22(seed: number, deals = 20000): EquityResult {
  const rng = mulberry32(seed);

  const aces = [
    [makeCard(12, 0), makeCard(12, 1)], // As Ah
    [makeCard(12, 0), makeCard(12, 2)], // As Ad (kept stable across deals)
  ];
  void aces;
  const heroCards = [makeCard(12, 0), makeCard(12, 1)]; // As Ah
  const villCards = [makeCard(0, 0), makeCard(0, 1)]; // 2s 2h

  const dead = new Set<number>([...heroCards, ...villCards]);
  const deck = fullDeck().filter((c) => !dead.has(c));

  let wins = 0;
  let splits = 0;
  let losses = 0;

  for (let deal = 0; deal < deals; deal++) {
    // Partial Fisher-Yates: draw 5 community cards without replacement.
    const board: number[] = [];
    for (let i = 0; i < 5; i++) {
      const j = i + Math.floor(rng() * (deck.length - i));
      const tmp = deck[i];
      deck[i] = deck[j];
      deck[j] = tmp;
      board.push(deck[i]);
    }

    const heroRank = eval7([...heroCards, ...board]);
    const villRank = eval7([...villCards, ...board]);

    if (heroRank > villRank) wins++;
    else if (heroRank < villRank) losses++;
    else splits++;
  }

  return { wins, splits, losses, equity: (wins + splits / 2) / deals };
}

