import { describe, expect, it } from "vitest";
import { eval5, eval7, parseCard, parseHand } from "../src/eval7";

describe("eval5 basics", () => {
  it("orders categories correctly", () => {
    const high = eval5(parseHand("2c 4d 6h 8s Js"));
    const pair = eval5(parseHand("2c 2d 6h 8s Js"));
    const twoPair = eval5(parseHand("2c 2d 6h 6s Js"));
    const trips = eval5(parseHand("2c 2d 2h 8s Js"));
    const straight = eval5(parseHand("2c 3d 4h 5s 6c"));
    const wheel = eval5(parseHand("Ac 2d 3h 4s 5c"));
    const flush = eval5(parseHand("2c 4c 6c 8c Jc"));
    const boat = eval5(parseHand("2c 2d 2h 8s 8c"));
    const quads = eval5(parseHand("2c 2d 2h 2s Jc"));
    const sFlush = eval5(parseHand("9c Tc Jc Qc Kc"));

    expect(pair).toBeGreaterThan(high);
    expect(twoPair).toBeGreaterThan(pair);
    expect(trips).toBeGreaterThan(twoPair);
    expect(straight).toBeGreaterThan(trips);
    expect(wheel).toBeLessThan(straight); // wheel is the lowest straight
    expect(flush).toBeGreaterThan(straight);
    expect(boat).toBeGreaterThan(flush);
    expect(quads).toBeGreaterThan(boat);
    expect(sFlush).toBeGreaterThan(quads);
  });

  it("wheel loses to six-high straight", () => {
    expect(eval5(parseHand("Ac 2d 3h 4s 5c"))).toBeLessThan(
      eval5(parseHand("2c 3d 4h 5s 6c"))
    );
  });
});

describe("eval7 vectors", () => {
  it("board of 66688 plays: board beats both KK and QQ, which split equally", () => {
    const board = parseHand("6s 6h 6d 8s 8h");
    const kk = [...parseHand("Kc Kd"), ...board];
    const qq = [...parseHand("Qc Qd"), ...board];

    const boardScore = eval7(board.length === 7 ? board : [...board, ...parseHand("2c 3c")]);
    const kkScore = eval7(kk);
    const qqScore = eval7(qq);

    // Board full house (sixes full of eights) beats both pocket pairs'
    // full houses (sixes full of kings / queens).
    expect(boardScore).toBeGreaterThan(kkScore);
    expect(boardScore).toBeGreaterThan(qqScore);
