import { describe, expect, it } from "vitest";
import { mulberry32, simulateAAvs22 } from "../src/equity";

describe("mulberry32", () => {
  it("is deterministic per seed and uniform-ish", () => {
    const a1 = mulberry32(42);
    const a2 = mulberry32(42);
    const seq1 = Array.from({ length: 100 }, () => a1());
    const seq2 = Array.from({ length: 100 }, () => a2());
    expect(seq1).toEqual(seq2);
    for (const v of seq1) {
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(1);
    }
  });
});

describe("AA vs 22 all-in preflop equity", () => {
  const N = 20000;

  it("lands near the known ~82% over 20000 seeded deals", () => {
    const res = simulateAAvs22(20260824, N);
    expect(res.wins + res.splits + res.losses).toBe(N);
    expect(res.equity).toBeGreaterThanOrEqual(0.78);
    expect(res.equity).toBeLessThanOrEqual(0.85);
  }, 30000);

  it("is bit-identical across runs with the same seed", () => {
    const r1 = simulateAAvs22(12345, N);
    const r2 = simulateAAvs22(12345, N);
    expect(Object.is(r1.equity, r2.equity)).toBe(true);
    expect(r1).toEqual(r2);
    // A different seed gives a different deal stream.
    const r3 = simulateAAvs22(12346, N);
    expect(Object.is(r1.equity, r3.equity)).toBe(false);
  }, 60000);
});

